-- ---------- functions ----------
CREATE OR REPLACE FUNCTION public.admin_recent_tips(_limit integer DEFAULT 8)
 RETURNS TABLE(id uuid, tipper text, recipient text, amount numeric, currency text, message text, created_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select t.id,
         coalesce(f.display_name, f.username, 'Member'),
         coalesce(w.name, r.display_name, r.username, 'Member'),
         t.amount,
         t.currency,
         coalesce(t.message, ''),
         t.created_at
    from public.tips t
    left join public.profiles f on f.id = t.from_user_id
    left join public.profiles r on r.id = t.to_user_id
    left join public.workspaces w on w.id = t.to_workspace_id
   where public.is_staff()
   order by t.created_at desc
   limit greatest(1, least(_limit, 25));
$function$
;
CREATE OR REPLACE FUNCTION public.admin_tip_stats()
 RETURNS TABLE(count bigint, amount numeric, currency text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*)::bigint,
         coalesce(sum(t.amount), 0),
         coalesce(
           (select currency from public.tips
             group by currency order by count(*) desc limit 1),
           'USD')
    from public.tips t
   where public.is_staff();
$function$
;
CREATE OR REPLACE FUNCTION public.apply_tip_fee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  bps integer;
begin
  bps := public.platform_fee_bps(new.to_user_id);
  new.fee_bps := bps;
  new.fee_amount := round(coalesce(new.amount, 0) * bps / 10000.0, 2);
  new.net_amount := round(coalesce(new.amount, 0) - new.fee_amount, 2);
  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.check_rate_limit(_bucket text, _limit integer, _window_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_window_seconds integer := greatest(1, coalesce(_window_seconds, 60));
  v_window_start   timestamptz;
  v_count          integer;
begin
  v_window_start := to_timestamp(
    floor(extract(epoch from now()) / v_window_seconds) * v_window_seconds
  );

  insert into public.rate_limits as rl (bucket, window_start, count)
  values (_bucket, v_window_start, 1)
  on conflict (bucket, window_start)
    do update set count = rl.count + 1
  returning rl.count into v_count;

  return v_count <= _limit;
end $function$
;
CREATE OR REPLACE FUNCTION public.current_profile_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select id from public.profiles where auth_user_id = auth.uid()
$function$
;
CREATE OR REPLACE FUNCTION public.earnings_snapshot(_profile uuid, _usd_rate numeric DEFAULT 130)
 RETURNS TABLE(gross_minor bigint, fees_minor bigint, net_minor bigint, withdrawn_minor bigint, available_minor bigint, gross_amount numeric, fees_amount numeric, net_amount numeric, withdrawn_amount numeric, available_amount numeric, gross_usd numeric, fees_usd numeric, net_usd numeric, withdrawn_usd numeric, available_usd numeric, tip_count bigint, currency text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if _profile is null
     or (public.current_profile_id() is distinct from _profile and not public.is_staff()) then
    return query select
      0::bigint, 0::bigint, 0::bigint, 0::bigint, 0::bigint,
      0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,
      0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,
      0::bigint,
      coalesce(current_setting('app.payout_currency', true), 'KES')::text;
    return;
  end if;

  return query
  with r as (
    -- Guard against a misconfigured (null / zero / negative) rate parameter.
    select case when coalesce(_usd_rate, 0) > 0 then _usd_rate else 130 end as usd_rate
  ),
  t as (
    select
      coalesce(sum(tp.amount), 0)                                as gross_amount,
      coalesce(sum(tp.fee_amount), 0)                            as fees_amount,
      coalesce(sum(tp.net_amount), 0)                            as sum_net_amount,
      coalesce(sum(tp.amount_minor), 0)::bigint                  as gross_minor,
      coalesce(sum((tp.fee_amount * 100)::bigint), 0)::bigint    as fees_minor,
      coalesce(sum((tp.net_amount * 100)::bigint), 0)::bigint    as sum_net_minor,
      count(*)                                                   as tip_count,
      (max(tp.currency))                                         as tip_currency,
      -- Per-row rate keeps historical FX correct; rows without one use today's.
      round(coalesce(sum(tp.amount     / coalesce(nullif(tp.exchange_rate, 0), r.usd_rate)), 0), 2) as sum_gross_usd,
      round(coalesce(sum(tp.fee_amount / coalesce(nullif(tp.exchange_rate, 0), r.usd_rate)), 0), 2) as sum_fees_usd,
      round(coalesce(sum(tp.net_amount / coalesce(nullif(tp.exchange_rate, 0), r.usd_rate)), 0), 2) as sum_net_usd
    from public.tips tp, r
    where tp.to_user_id = _profile
      and tp.to_workspace_id is null
  ),
  p as (
    select
      coalesce(sum(pp.amount), 0)                            as withdrawn_amount,
      coalesce(sum((pp.amount * 100)::bigint), 0)::bigint    as withdrawn_minor,
      -- Debit the GROSS request: net transfer + platform fee (fee_usd x the
      -- row's own rate converts it back into settlement units).
      coalesce(sum(pp.amount + coalesce(pp.fee_usd, 0) * coalesce(nullif(pp.exchange_rate, 0), 130)), 0) as withdrawn_gross_amount,
      (coalesce(sum((pp.amount + coalesce(pp.fee_usd, 0) * coalesce(nullif(pp.exchange_rate, 0), 130)) * 100), 0))::bigint as withdrawn_gross_minor,
      round(coalesce(sum(coalesce(
        pp.amount_usd,
        pp.amount / coalesce(nullif(pp.exchange_rate, 0), r.usd_rate)
      )), 0), 2)                                             as sum_withdrawn_usd
    from public.payouts pp, r
    where pp.user_id = _profile
      and pp.workspace_id is null
      and pp.status not in ('failed', 'reversed', 'declined')
  )
  select
    t.gross_minor,
    t.fees_minor,
    t.sum_net_minor,
    p.withdrawn_minor,
    greatest(0, t.sum_net_minor - p.withdrawn_gross_minor)    as available_minor,
    t.gross_amount,
    t.fees_amount,
    t.sum_net_amount,
    p.withdrawn_amount,
    greatest(0, t.sum_net_amount - p.withdrawn_gross_amount)  as available_amount,
    t.sum_gross_usd,
    t.sum_fees_usd,
    t.sum_net_usd,
    p.sum_withdrawn_usd,
    greatest(0, t.sum_net_usd - p.sum_withdrawn_usd)               as available_usd,
    t.tip_count,
    coalesce(t.tip_currency, current_setting('app.payout_currency', true), 'KES')
  from t, p;
end $function$
;
CREATE OR REPLACE FUNCTION public.enforce_content_rate_limit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  lim integer;
begin
  select rate_limit_requests_per_min into lim from public.system_settings where id = 1;
  -- No settings row configured yet: never block writes on a missing limiter.
  if lim is null or lim <= 0 then
    return new;
  end if;
  if not public.check_rate_limit('content_write:' || new.user_id, lim, 60) then
    raise exception 'rate limit exceeded: too many requests, slow down'
      using errcode = 'PT429';
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.enforce_space_capacity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_space      public.spaces%rowtype;
  v_host_plan  text;
  v_max        integer;
  v_current    integer;
begin
  select * into v_space from public.spaces where id = new.space_id;
  if not found then
    return new;
  end if;

  -- The host is always allowed into their own room, and only live rooms are capped.
  if new.user_id = v_space.host_id or not v_space.live then
    return new;
  end if;

  select plan into v_host_plan from public.profiles where id = v_space.host_id;
  select spaces_max_listeners into v_max
    from public.plan_limits
   where plan = coalesce(v_host_plan, 'free');
  if v_max is null then
    v_max := 10;
  end if;

  select count(*) into v_current
    from public.space_participants
   where space_id = new.space_id
     and user_id <> v_space.host_id;

  if v_current >= v_max then
    raise exception 'SPACE_AT_CAPACITY' using errcode = 'P0001';
  end if;

  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.enqueue_webhook_event(_profile uuid, _event text, _payload jsonb)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  insert into public.webhook_deliveries (webhook_id, event, payload)
  select w.id, _event, jsonb_build_object('event', _event, 'created_at', now(), 'data', _payload)
  from public.webhooks w
  where w.user_id = _profile and w.active
    and (w.events ? _event or w.events ? '*' or jsonb_array_length(w.events) = 0);
$function$
;
CREATE OR REPLACE FUNCTION public.get_workspace_profile(_workspace_id uuid)
 RETURNS TABLE(id uuid, name text, logo_emoji text, avatar_url text, bio text, created_at timestamp with time zone, post_count bigint, member_count bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    w.id,
    w.name,
    w.logo_emoji,
    w.avatar_url,
    w.bio,
    w.created_at,
    (
      select count(*)
      from public.posts p
      where p.workspace_id = w.id
        and p.hidden = false
    ) as post_count,
    (
      select count(*)
      from public.workspace_members m
      where m.workspace_id = w.id
        and m.status = 'active'
    ) as member_count
  from public.workspaces w
  where w.id = _workspace_id;
$function$
;
CREATE OR REPLACE FUNCTION public.grant_bootstrap_admin()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.user_roles (user_id, role)
  select new.id, b.role
    from public.bootstrap_admins b
   where lower(b.email) = lower(new.email)
  on conflict do nothing;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.guard_profile_plan_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.plan IS DISTINCT FROM OLD.plan AND auth.role() <> 'service_role' THEN
    NEW.plan := OLD.plan;
  END IF;
  RETURN NEW;
END;
$function$
;
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare base text; candidate text; n integer := 0;
begin
  base := lower(regexp_replace(coalesce(new.raw_user_meta_data->>'username', split_part(new.email,'@',1), 'user'), '[^a-z0-9_]', '', 'g'));
  if base = '' then base := 'user'; end if;
  candidate := base;
  while exists (select 1 from public.profiles where username = candidate) loop
    n := n + 1; candidate := base || n::text;
  end loop;
  insert into public.profiles (auth_user_id, username, display_name, avatar_url)
  values (new.id, candidate,
          coalesce(
            nullif(trim(new.raw_user_meta_data->>'display_name'), ''),
            nullif(trim(new.raw_user_meta_data->>'full_name'), ''),
            nullif(trim(new.raw_user_meta_data->>'name'), ''),          -- Google/OIDC
            candidate),
          coalesce(
            nullif(new.raw_user_meta_data->>'avatar_url', ''),
            nullif(new.raw_user_meta_data->>'picture', '')));           -- Google raw claim
  insert into public.user_roles (user_id, role) values (new.id, 'user') on conflict do nothing;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid, _role app_role)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.user_roles where user_id = _user_id and role = _role)
$function$
;
CREATE OR REPLACE FUNCTION public.is_active_profile()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select auth.role() = 'service_role'
     or coalesce(
          (select p.status = 'active' from public.profiles p where p.id = public.current_profile_id()),
          false
        )
$function$
;
CREATE OR REPLACE FUNCTION public.is_pro_profile(_profile_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- Mirrors plan-guard.server.ts: an active pro subscription or a pro profile.
  select exists (
    select 1 from public.profiles p
    where p.id = _profile_id and p.plan = 'pro'
  ) or exists (
    select 1 from public.subscriptions s
    where s.user_id = _profile_id and s.plan = 'pro' and s.status = 'active'
  );
$function$
;
CREATE OR REPLACE FUNCTION public.is_staff()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.has_role(auth.uid(),'admin') or public.has_role(auth.uid(),'moderator')
$function$
;
CREATE OR REPLACE FUNCTION public.is_workspace_member(_workspace_id uuid, _profile_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.workspaces w where w.id = _workspace_id and w.owner_id = _profile_id)
      or exists (select 1 from public.workspace_members m
                 where m.workspace_id = _workspace_id and m.user_id = _profile_id and m.status = 'active')
$function$
;
CREATE OR REPLACE FUNCTION public.notify(_recipient uuid, _actor uuid, _type text, _body text, _post_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if _recipient is null or _recipient = _actor then return; end if;
  insert into public.notifications (recipient_id, actor_id, type, body, post_id)
  values (_recipient, _actor, _type, _body, _post_id);
end $function$
;
CREATE OR REPLACE FUNCTION public.owns_profile(_profile_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.profiles p where p.id = _profile_id and p.auth_user_id = auth.uid())
$function$
;
CREATE OR REPLACE FUNCTION public.platform_fee_bps(_profile_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select l.fee_bps
       from public.plan_limits l
      where l.plan = coalesce(
        (select s.plan from public.subscriptions s
          where s.user_id = _profile_id and s.status = 'active' limit 1),
        (select p.plan from public.profiles p where p.id = _profile_id),
        'free')),
    500
  )
$function$
;
CREATE OR REPLACE FUNCTION public.prune_rate_limits()
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  delete from public.rate_limits where window_start < now() - interval '1 day'
$function$
;
CREATE OR REPLACE FUNCTION public.respond_workspace_invite(_member_id uuid, _accept boolean)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare m record; ws record; me uuid := public.current_profile_id();
begin
  select * into m from public.workspace_members where id = _member_id for update;
  if m is null or m.user_id is distinct from me then raise exception 'Invite not found'; end if;
  if m.status <> 'invited' then return m.status; end if;
  update public.workspace_members set status = case when _accept then 'active' else 'declined' end where id = _member_id;
  select * into ws from public.workspaces where id = m.workspace_id;
  update public.notifications set action = action || jsonb_build_object('state', case when _accept then 'accepted' else 'declined' end), read = true
    where recipient_id = me and action->>'member_id' = _member_id::text;
  insert into public.notifications (recipient_id, actor_id, type, body, link)
  values (ws.owner_id, me, 'workspace',
          format('%s your invite to “%s”', case when _accept then 'accepted' else 'declined' end, ws.name),
          '/settings?section=workspaces');
  return case when _accept then 'active' else 'declined' end;
end $function$
;
CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin new.updated_at = now(); return new; end $function$
;
CREATE OR REPLACE FUNCTION public.settle_paystack_transaction(_reference text, _tx jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pay      record;
  v_status   text;
  v_provider_amount bigint;
  v_provider_currency text;
  v_paid_at  timestamptz;
  v_customer text;
  v_pm       jsonb;
  v_bps      integer;
  v_net_major numeric;
  v_fee_major numeric;
  v_tip_id   uuid;
  v_amount_major numeric;
begin
  -- Serialise concurrent deliveries for this exact reference.
  perform pg_advisory_xact_lock(hashtext(_reference));

  v_status          := lower(coalesce(_tx->>'status', ''));
  v_provider_amount := nullif(_tx->>'amount', '')::bigint;         -- minor units, from provider
  v_provider_currency := upper(coalesce(_tx->>'currency', ''));
  v_paid_at         := coalesce(
    nullif(_tx->>'paid_at', '')::timestamptz,
    to_timestamp(nullif(_tx->>'timestamp', '')::double precision),
    now());
  v_customer        := _tx->'customer'->>'customer_code';

  -- Keep only non-sensitive provider fields; never persist the full payload.
  update public.payments
     set updated_at = now()
   where reference = _reference;

  select * into v_pay from public.payments where reference = _reference;
  if not found then
    return jsonb_build_object('status', 'unknown_reference');
  end if;

  -- Failed / pending provider status: record it, settle nothing.
  if v_status <> 'success' then
    update public.payments
       set status = case when v_status in ('failed','abandoned') then 'failed' else status end,
           settle_error = coalesce(_tx->>'gateway_response', 'provider_status:' || v_status),
           updated_at = now()
     where reference = _reference and status <> 'success';
    return jsonb_build_object('status', 'not_success', 'provider_status', v_status);
  end if;

  -- Currency must match what we asked to charge.
  if v_provider_currency <> '' and v_pay.currency is not null
     and v_provider_currency <> upper(v_pay.currency) then
    update public.payments
       set settle_error = 'currency_mismatch:' || v_provider_currency, updated_at = now()
     where reference = _reference;
    return jsonb_build_object('status', 'currency_mismatch',
                              'expected', v_pay.currency, 'received', v_provider_currency);
  end if;

  -- The amount actually paid must equal what we intended to charge.
  if v_provider_amount is not null and v_pay.expected_amount_minor is not null
     and v_provider_amount <> v_pay.expected_amount_minor then
    update public.payments
       set settle_error = 'amount_mismatch:' || v_provider_amount, updated_at = now()
     where reference = _reference;
    return jsonb_build_object('status', 'amount_mismatch',
                              'expected_minor', v_pay.expected_amount_minor,
                              'received_minor', v_provider_amount);
  end if;

  -- Idempotent, single-use transition. Only this statement may credit value.
  update public.payments
     set status = 'success',
         paid_at = coalesce(paid_at, v_paid_at),
         amount_minor = coalesce(v_provider_amount, amount_minor, expected_amount_minor),
         raw = jsonb_build_object(
                 'reference', _reference,
                 'status', 'success',
                 'paid_at', v_paid_at,
                 'channel', _tx->>'channel',
                 'gateway', _tx->>'gateway'),
         settle_error = null,
         updated_at = now()
   where reference = _reference and status <> 'success'
  returning id into v_pay.id;

  if v_pay.id is null then
    -- A concurrent delivery already settled it.
    return jsonb_build_object('status', 'already_settled');
  end if;

  -- Reload authoritative row fields after the flip. FIX: `select *` (the full
  -- row) — a narrow column list would replace the record's structure and drop
  -- `amount`, crashing the coalesce below on payloads without an amount.
  select * into v_pay from public.payments where reference = _reference;

  -- Derive a settled major-unit amount in the settlement currency.
  v_amount_major := round(coalesce(v_provider_amount, v_pay.expected_amount_minor,
                                   v_pay.amount * 100)::numeric / 100.0, 2);

  if coalesce(v_pay.kind, 'plan') = 'tip' then
    if v_pay.recipient_id is null then
      update public.payments set settle_error = 'missing_recipient', updated_at = now()
        where reference = _reference;
      return jsonb_build_object('status', 'error', 'reason', 'missing_recipient');
    end if;

    -- Withdrawal-time fees: the tip is credited in full and the platform's
    -- take (5/3/1% by plan) is deducted when the creator cashes out.
    v_bps := 0;
    v_fee_major := 0;
    v_net_major := v_amount_major;

    insert into public.tips
      (from_user_id, to_user_id, to_workspace_id, post_id, amount, amount_minor, currency, message,
       fee_bps, fee_amount, net_amount, legacy_fee, payment_reference, exchange_rate, quoted_amount_usd)
    values
      (v_pay.user_id, v_pay.recipient_id, v_pay.recipient_workspace_id, v_pay.tip_post_id, v_amount_major,
       (v_amount_major * 100)::bigint, v_pay.currency, coalesce(v_pay.tip_message, ''),
       v_bps, v_fee_major, v_net_major, false, _reference, v_pay.exchange_rate, v_pay.quoted_amount_usd)
    returning id into v_tip_id;

    -- t_tips_after emits the notification; we only report here.
    return jsonb_build_object('status', 'success', 'kind', 'tip', 'tip_id', v_tip_id,
                              'amount', v_amount_major, 'currency', v_pay.currency,
                              'workspace', v_pay.recipient_workspace_id);
  end if;

  -- Plan activation. Sanitise card data to the PCI non-sensitive allowlist.
  v_pm := jsonb_strip_nulls(jsonb_build_object(
    'brand', coalesce(_tx->'authorization'->>'card_type', _tx->'authorization'->>'channel'),
    'last4', _tx->'authorization'->>'last4',
    'exp_month', _tx->'authorization'->>'exp_month',
    'exp_year', _tx->'authorization'->>'exp_year',
    'channel', _tx->'authorization'->>'channel'
  ));

  update public.profiles set plan = v_pay.plan where id = v_pay.user_id;

  insert into public.subscriptions
    (user_id, plan, billing_cycle, status, provider, provider_customer_id, payment_method, renews_at, updated_at)
  values
    (v_pay.user_id, v_pay.plan, v_pay.billing_cycle, 'active', 'paystack', v_customer, v_pm,
     now() + (case when v_pay.billing_cycle = 'annual' then interval '365 days' else interval '30 days' end),
     now())
  on conflict (user_id) do update set
    plan = excluded.plan,
    billing_cycle = excluded.billing_cycle,
    status = 'active',
    provider = 'paystack',
    provider_customer_id = coalesce(excluded.provider_customer_id, subscriptions.provider_customer_id),
    payment_method = excluded.payment_method,
    renews_at = excluded.renews_at,
    updated_at = now();

  return jsonb_build_object('status', 'success', 'kind', 'plan',
                            'plan', v_pay.plan, 'cycle', v_pay.billing_cycle);
end $function$
;
CREATE OR REPLACE FUNCTION public.stamp_call_signal_sender()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  new.from_profile := public.current_profile_id();
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.t_comments_after()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pid uuid; author uuid; parent_author uuid;
begin
  pid := coalesce(new.post_id, old.post_id);
  update public.posts p set comment_count = (select count(*) from public.comments c where c.post_id = pid) where p.id = pid;
  if tg_op = 'INSERT' then
    select user_id into author from public.posts where id = pid;
    if new.parent_id is not null then
      select user_id into parent_author from public.comments where id = new.parent_id;
      perform public.notify(parent_author, new.user_id, 'reply', 'replied to your comment', pid);
    end if;
    perform public.notify(author, new.user_id, 'comment', 'commented on your post', pid);
  end if;
  return null;
end $function$
;
CREATE OR REPLACE FUNCTION public.t_follows_after()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare f uuid; t uuid;
begin
  f := coalesce(new.follower_id, old.follower_id);
  t := coalesce(new.target_id, old.target_id);
  update public.profiles p set following = (select count(*) from public.follows x where x.follower_id = f) where p.id = f;
  update public.profiles p set followers = (select count(*) from public.follows x where x.target_id = t) where p.id = t;
  if tg_op = 'INSERT' then
    perform public.notify(t, f, 'follow', 'started following you');
  end if;
  return null;
end $function$
;
CREATE OR REPLACE FUNCTION public.t_impressions_after()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.posts set view_count = view_count + 1 where id = new.post_id;
  return null;
end $function$
;
CREATE OR REPLACE FUNCTION public.t_likes_after()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pid uuid; author uuid;
begin
  pid := coalesce(new.post_id, old.post_id);
  update public.posts p set like_count = (select count(*) from public.likes l where l.post_id = pid) where p.id = pid;
  if tg_op = 'INSERT' then
    select user_id into author from public.posts where id = pid;
    perform public.notify(author, new.user_id, 'like', 'liked your post', pid);
  end if;
  return null;
end $function$
;
CREATE OR REPLACE FUNCTION public.t_messages_after()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare a uuid; b uuid; other uuid;
begin
  select user_a, user_b into a, b from public.conversations where id = new.conversation_id;
  update public.conversations
     set preview = left(coalesce(new.body, 'Attachment'), 140), updated_at = now()
   where id = new.conversation_id;
  other := case when new.sender_id = a then b else a end;
  perform public.notify(other, new.sender_id, 'message', 'sent you a message');
  return null;
end $function$
;
CREATE OR REPLACE FUNCTION public.t_messages_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.role() = 'service_role' or public.is_staff() or public.owns_profile(old.sender_id) then
    return new;
  end if;
  new.body       := old.body;
  new.media_url  := old.media_url;
  new.sender_id  := old.sender_id;
  new.created_at := old.created_at;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.t_profiles_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Follower/following are derived facts: always recompute from `follows`,
  -- regardless of caller. See header note for why pinning to OLD broke the
  -- counter triggers.
  new.followers := (select count(*)::integer from public.follows f where f.target_id = old.id);
  new.following := (select count(*)::integer from public.follows f where f.follower_id = old.id);

  if auth.role() = 'service_role' or public.is_staff() then
    return new;
  end if;
  new.plan           := old.plan;
  new.verified       := old.verified;
  new.status         := old.status;
  new.warning_count  := old.warning_count;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.t_reposts_after()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare pid uuid; author uuid;
begin
  pid := coalesce(new.post_id, old.post_id);
  update public.posts p set repost_count = (select count(*) from public.reposts r where r.post_id = pid) where p.id = pid;
  if tg_op = 'INSERT' then
    select user_id into author from public.posts where id = pid;
    perform public.notify(author, new.user_id, 'repost', 'reposted your post', pid);
  end if;
  return null;
end $function$
;
CREATE OR REPLACE FUNCTION public.t_space_participants_after()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare sid uuid;
begin
  sid := coalesce(new.space_id, old.space_id);
  update public.spaces s set listeners = (select count(*) from public.space_participants p where p.space_id = sid) where s.id = sid;
  return null;
end $function$
;
CREATE OR REPLACE FUNCTION public.t_space_participants_role_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  is_host boolean;
begin
  select exists(
    select 1 from public.spaces s
    where s.id = new.space_id and owns_profile(s.host_id)
  ) into is_host;

  if is_host or is_staff() then
    return new;
  end if;

  -- Non-host actors: only allowed to touch their own row.
  if not owns_profile(new.user_id) then
    raise exception 'Only the host can manage other participants';
  end if;

  -- Non-host actors cannot promote themselves or anyone into speaker/host.
  if new.role is distinct from old.role and new.role <> 'listener' then
    raise exception 'Only the host can invite someone to speak';
  end if;

  -- Non-host actors cannot force-unmute a role change they don't own beyond their own mic state.
  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.t_space_replay_view_after()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update public.spaces
    set replay_count = (select count(*) from public.space_replay_views where space_id = new.space_id)
    where id = new.space_id;
  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.t_spaces_recording_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Hard ceiling regardless of client config, to stop abusive uploads.
  if new.recording_bytes > 1073741824 then -- 1 GiB
    raise exception 'Recording exceeds the maximum allowed size';
  end if;
  return new;
end;
$function$
;
