CREATE OR REPLACE FUNCTION public.trg_workspace_invite()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ws record; invitee uuid; used int; handle text;
begin
  if new.status <> 'invited' then return new; end if;
  select * into ws from public.workspaces where id = new.workspace_id;
  select count(*) into used from public.workspace_members where workspace_id = new.workspace_id and status in ('active','invited');
  if used >= ws.seats_total then raise exception 'All % seats are in use. Upgrade to add more teammates.', ws.seats_total; end if;
  if new.user_id is null then
    handle := lower(regexp_replace(trim(new.email), '^@', ''));
    select p.id into invitee from public.profiles p
      left join auth.users u on u.id = p.auth_user_id
      where lower(u.email) = handle or lower(p.username) = handle limit 1;
    new.user_id := invitee;
  end if;
  if exists (select 1 from public.workspace_members m where m.workspace_id = new.workspace_id
             and (m.user_id = new.user_id or lower(m.email) = lower(new.email)) and m.status in ('active','invited')) then
    raise exception 'That person is already on this team or has a pending invite.';
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.trg_workspace_invite_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ws record;
begin
  if new.status = 'invited' and new.user_id is not null then
    select * into ws from public.workspaces where id = new.workspace_id;
    insert into public.notifications (recipient_id, actor_id, type, body, link, action)
    values (new.user_id, ws.owner_id, 'workspace_invite',
            format('invited you to join the team “%s” as %s', ws.name, new.role),
            '/settings?section=workspaces',
            jsonb_build_object('kind','workspace_invite','member_id', new.id, 'workspace_id', ws.id, 'state','pending'));
  end if;
  return new;
end $function$
;
CREATE OR REPLACE FUNCTION public.workspace_earnings_snapshot(_workspace uuid, _usd_rate numeric DEFAULT 130)
 RETURNS TABLE(gross_minor bigint, fees_minor bigint, net_minor bigint, withdrawn_minor bigint, available_minor bigint, gross_amount numeric, fees_amount numeric, net_amount numeric, withdrawn_amount numeric, available_amount numeric, gross_usd numeric, fees_usd numeric, net_usd numeric, withdrawn_usd numeric, available_usd numeric, tip_count bigint, currency text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if _workspace is null
     or (public.workspace_role(_workspace, public.current_profile_id()) is distinct from 'Owner'
         and not public.is_staff()) then
    return query select
      0::bigint, 0::bigint, 0::bigint, 0::bigint, 0::bigint,
      0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,
      0::numeric, 0::numeric, 0::numeric, 0::numeric, 0::numeric,
      0::bigint,
      coalesce(current_setting('app.payout_currency', true), 'KES')::text;
    return;
  end if;

  return query
  with r as (
    select case when coalesce(_usd_rate, 0) > 0 then _usd_rate else 130 end as usd_rate
  ),
  t as (
    select
      coalesce(sum(tp.amount), 0)                                as gross_amount,
      coalesce(sum(tp.fee_amount), 0)                            as fees_amount,
      coalesce(sum(tp.net_amount), 0)                            as sum_net_amount,
      coalesce(sum(tp.amount_minor), 0)::bigint                  as gross_minor,
      coalesce(sum((tp.fee_amount * 100)::bigint), 0)::bigint    as fees_minor,
      coalesce(sum((tp.net_amount * 100)::bigint), 0)::bigint    as sum_net_minor,
      count(*)                                                   as tip_count,
      (max(tp.currency))                                         as tip_currency,
      round(coalesce(sum(tp.amount     / coalesce(nullif(tp.exchange_rate, 0), r.usd_rate)), 0), 2) as sum_gross_usd,
      round(coalesce(sum(tp.fee_amount / coalesce(nullif(tp.exchange_rate, 0), r.usd_rate)), 0), 2) as sum_fees_usd,
      round(coalesce(sum(tp.net_amount / coalesce(nullif(tp.exchange_rate, 0), r.usd_rate)), 0), 2) as sum_net_usd
    from public.tips tp, r
    where tp.to_workspace_id = _workspace
  ),
  p as (
    select
      coalesce(sum(pp.amount), 0)                            as withdrawn_amount,
      coalesce(sum((pp.amount * 100)::bigint), 0)::bigint    as withdrawn_minor,
      coalesce(sum(pp.amount + coalesce(pp.fee_usd, 0) * coalesce(nullif(pp.exchange_rate, 0), 130)), 0) as withdrawn_gross_amount,
      (coalesce(sum((pp.amount + coalesce(pp.fee_usd, 0) * coalesce(nullif(pp.exchange_rate, 0), 130)) * 100), 0))::bigint as withdrawn_gross_minor,
      round(coalesce(sum(coalesce(
        pp.amount_usd,
        pp.amount / coalesce(nullif(pp.exchange_rate, 0), r.usd_rate)
      )), 0), 2)                                             as sum_withdrawn_usd
    from public.payouts pp, r
    where pp.workspace_id = _workspace
      and pp.status not in ('failed', 'reversed', 'declined')
  )
  select
    t.gross_minor,
    t.fees_minor,
    t.sum_net_minor,
    p.withdrawn_minor,
    greatest(0, t.sum_net_minor - p.withdrawn_gross_minor)    as available_minor,
    t.gross_amount,
    t.fees_amount,
    t.sum_net_amount,
    p.withdrawn_amount,
    greatest(0, t.sum_net_amount - p.withdrawn_gross_amount)  as available_amount,
    t.sum_gross_usd,
    t.sum_fees_usd,
    t.sum_net_usd,
    p.sum_withdrawn_usd,
    greatest(0, t.sum_net_usd - p.sum_withdrawn_usd)               as available_usd,
    t.tip_count,
    coalesce(t.tip_currency, current_setting('app.payout_currency', true), 'KES')
  from t, p;
end $function$
;
CREATE OR REPLACE FUNCTION public.workspace_role(_workspace_id uuid, _profile_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when exists (select 1 from public.workspaces w where w.id = _workspace_id and w.owner_id = _profile_id) then 'Owner'
    else (select m.role from public.workspace_members m
          where m.workspace_id = _workspace_id and m.user_id = _profile_id and m.status = 'active' limit 1)
  end
$function$
;

