-- ---------- policies ----------
create policy "api keys owner delete" on public."api_keys" as PERMISSIVE for DELETE to authenticated using ((user_id IN ( SELECT profiles.id
   FROM profiles
  WHERE (profiles.auth_user_id = auth.uid()))));
create policy "api keys owner read" on public."api_keys" as PERMISSIVE for SELECT to authenticated using ((user_id IN ( SELECT profiles.id
   FROM profiles
  WHERE (profiles.auth_user_id = auth.uid()))));
create policy "api keys owner revoke" on public."api_keys" as PERMISSIVE for UPDATE to authenticated using ((user_id IN ( SELECT profiles.id
   FROM profiles
  WHERE (profiles.auth_user_id = auth.uid())))) with check ((user_id IN ( SELECT profiles.id
   FROM profiles
  WHERE (profiles.auth_user_id = auth.uid()))));
create policy "api requests owner read" on public."api_requests" as PERMISSIVE for SELECT to authenticated using ((key_id IN ( SELECT k.id
   FROM (api_keys k
     JOIN profiles p ON ((p.id = k.user_id)))
  WHERE (p.auth_user_id = auth.uid()))));
create policy "audit staff read" on public."audit_logs" as PERMISSIVE for SELECT to authenticated using (is_staff());
create policy "bookmarks owner all" on public."bookmarks" as PERMISSIVE for ALL to authenticated using (owns_profile(user_id)) with check (owns_profile(user_id));
create policy "branding owner update" on public."branding_settings" as PERMISSIVE for UPDATE to authenticated using (owns_profile(user_id));
create policy "branding owner write" on public."branding_settings" as PERMISSIVE for INSERT to authenticated with check (owns_profile(user_id));
create policy "branding public read" on public."branding_settings" as PERMISSIVE for SELECT using (true);
create policy "call_signals participant read" on public."call_signals" as PERMISSIVE for SELECT to authenticated using ((EXISTS ( SELECT 1
   FROM calls c
  WHERE ((c.id = call_signals.call_id) AND ((c.caller_id = current_profile_id()) OR (c.callee_id = current_profile_id()))))));
create policy "call_signals participant write" on public."call_signals" as PERMISSIVE for INSERT to authenticated with check (((from_profile = current_profile_id()) AND (EXISTS ( SELECT 1
   FROM calls c
  WHERE ((c.id = call_signals.call_id) AND ((c.caller_id = current_profile_id()) OR (c.callee_id = current_profile_id())))))));
create policy "calls participant read" on public."calls" as PERMISSIVE for SELECT to authenticated using ((owns_profile(caller_id) OR owns_profile(callee_id)));
create policy "calls participant update" on public."calls" as PERMISSIVE for UPDATE to authenticated using ((owns_profile(caller_id) OR owns_profile(callee_id)));
create policy "calls participant write" on public."calls" as PERMISSIVE for INSERT to authenticated with check (owns_profile(caller_id));
create policy "comments owner delete" on public."comments" as PERMISSIVE for DELETE to authenticated using ((owns_profile(user_id) OR is_staff()));
create policy "comments owner update" on public."comments" as PERMISSIVE for UPDATE to authenticated using ((owns_profile(user_id) OR is_staff())) with check ((owns_profile(user_id) OR is_staff()));
create policy "comments owner write" on public."comments" as PERMISSIVE for INSERT to authenticated with check ((owns_profile(user_id) AND is_active_profile()));
create policy "comments public read" on public."comments" as PERMISSIVE for SELECT using ((is_staff() OR owns_profile(user_id) OR (EXISTS ( SELECT 1
   FROM posts p
  WHERE ((p.id = comments.post_id) AND (NOT p.hidden))))));
create policy "conversations participant read" on public."conversations" as PERMISSIVE for SELECT to authenticated using ((owns_profile(user_a) OR owns_profile(user_b)));
create policy "conversations participant update" on public."conversations" as PERMISSIVE for UPDATE to authenticated using ((owns_profile(user_a) OR owns_profile(user_b)));
create policy "conversations participant write" on public."conversations" as PERMISSIVE for INSERT to authenticated with check ((owns_profile(user_a) OR owns_profile(user_b)));
create policy "feed prefs owner all" on public."feed_preferences" as PERMISSIVE for ALL to authenticated using (owns_profile(user_id)) with check (owns_profile(user_id));
create policy "follows owner delete" on public."follows" as PERMISSIVE for DELETE to authenticated using (owns_profile(follower_id));
create policy "follows owner write" on public."follows" as PERMISSIVE for INSERT to authenticated with check (owns_profile(follower_id));
create policy "follows public read" on public."follows" as PERMISSIVE for SELECT using (true);
create policy "likes owner delete" on public."likes" as PERMISSIVE for DELETE to authenticated using (owns_profile(user_id));
create policy "likes owner write" on public."likes" as PERMISSIVE for INSERT to authenticated with check (owns_profile(user_id));
create policy "likes public read" on public."likes" as PERMISSIVE for SELECT using (true);
create policy "reactions participant read" on public."message_reactions" as PERMISSIVE for SELECT to authenticated using ((EXISTS ( SELECT 1
   FROM (messages m
     JOIN conversations c ON ((c.id = m.conversation_id)))
  WHERE ((m.id = message_reactions.message_id) AND (owns_profile(c.user_a) OR owns_profile(c.user_b))))));
create policy "reactions self delete" on public."message_reactions" as PERMISSIVE for DELETE to authenticated using (owns_profile(user_id));
create policy "reactions self write" on public."message_reactions" as PERMISSIVE for INSERT to authenticated with check (owns_profile(user_id));
create policy "messages participant read" on public."messages" as PERMISSIVE for SELECT to authenticated using ((EXISTS ( SELECT 1
   FROM conversations c
  WHERE ((c.id = messages.conversation_id) AND (owns_profile(c.user_a) OR owns_profile(c.user_b))))));
create policy "messages participant update" on public."messages" as PERMISSIVE for UPDATE to authenticated using ((EXISTS ( SELECT 1
   FROM conversations c
  WHERE ((c.id = messages.conversation_id) AND (owns_profile(c.user_a) OR owns_profile(c.user_b))))));
create policy "messages sender delete" on public."messages" as PERMISSIVE for DELETE to authenticated using (owns_profile(sender_id));
create policy "messages sender write" on public."messages" as PERMISSIVE for INSERT to authenticated with check ((owns_profile(sender_id) AND is_active_profile() AND (EXISTS ( SELECT 1
   FROM conversations c
  WHERE ((c.id = messages.conversation_id) AND (owns_profile(c.user_a) OR owns_profile(c.user_b)))))));
create policy "monetization owner all" on public."monetization_settings" as PERMISSIVE for ALL to authenticated using (owns_profile(user_id)) with check (owns_profile(user_id));
create policy "notifications insert" on public."notifications" as PERMISSIVE for INSERT to authenticated with check ((is_staff() OR owns_profile(actor_id)));
create policy "notifications owner delete" on public."notifications" as PERMISSIVE for DELETE to authenticated using (owns_profile(recipient_id));
create policy "notifications owner read" on public."notifications" as PERMISSIVE for SELECT to authenticated using (owns_profile(recipient_id));
create policy "notifications owner update" on public."notifications" as PERMISSIVE for UPDATE to authenticated using (owns_profile(recipient_id));
create policy "payments owner read" on public."payments" as PERMISSIVE for SELECT to authenticated using ((owns_profile(user_id) OR is_staff()));
create policy "payouts owner read" on public."payouts" as PERMISSIVE for SELECT to authenticated using ((owns_profile(user_id) OR is_staff()));
create policy "payouts owner write" on public."payouts" as PERMISSIVE for INSERT to authenticated with check (owns_profile(user_id));
create policy "plan_limits public read" on public."plan_limits" as PERMISSIVE for SELECT using (true);
create policy "poll votes owner write" on public."poll_votes" as PERMISSIVE for INSERT to authenticated with check (owns_profile(user_id));
create policy "poll votes public read" on public."poll_votes" as PERMISSIVE for SELECT using (true);
create policy "impressions insert" on public."post_impressions" as PERMISSIVE for INSERT to authenticated with check (((user_id IS NULL) OR owns_profile(user_id)));
create policy "impressions read" on public."post_impressions" as PERMISSIVE for SELECT to authenticated using ((is_staff() OR (EXISTS ( SELECT 1
   FROM posts p
  WHERE ((p.id = post_impressions.post_id) AND owns_profile(p.user_id))))));
create policy "posts owner delete" on public."posts" as PERMISSIVE for DELETE to authenticated using ((owns_profile(user_id) OR is_staff()));
create policy "posts owner update" on public."posts" as PERMISSIVE for UPDATE to authenticated using ((owns_profile(user_id) OR is_staff()));
create policy "posts owner write" on public."posts" as PERMISSIVE for INSERT to authenticated with check ((owns_profile(user_id) AND is_active_profile() AND ((workspace_id IS NULL) OR (workspace_role(workspace_id, current_profile_id()) = ANY (ARRAY['Owner'::text, 'Admin'::text, 'Editor'::text])))));
create policy "posts public read" on public."posts" as PERMISSIVE for SELECT using (((NOT hidden) OR owns_profile(user_id) OR is_staff()));
create policy "profiles public read" on public."profiles" as PERMISSIVE for SELECT using (true);
create policy "profiles self insert" on public."profiles" as PERMISSIVE for INSERT to authenticated with check ((auth_user_id = auth.uid()));
create policy "profiles self update" on public."profiles" as PERMISSIVE for UPDATE to authenticated using (((auth_user_id = auth.uid()) OR is_staff()));
create policy "reports read" on public."reports" as PERMISSIVE for SELECT to authenticated using ((owns_profile(reporter_id) OR is_staff()));
create policy "reports reporter insert" on public."reports" as PERMISSIVE for INSERT to authenticated with check (owns_profile(reporter_id));
create policy "reports staff update" on public."reports" as PERMISSIVE for UPDATE to authenticated using (is_staff());
create policy "reposts owner delete" on public."reposts" as PERMISSIVE for DELETE to authenticated using ((owns_profile(user_id) OR ((workspace_id IS NOT NULL) AND (workspace_role(workspace_id, current_profile_id()) = ANY (ARRAY['Owner'::text, 'Admin'::text])))));
create policy "reposts owner write" on public."reposts" as PERMISSIVE for INSERT to authenticated with check ((owns_profile(user_id) AND ((workspace_id IS NULL) OR (workspace_role(workspace_id, current_profile_id()) = ANY (ARRAY['Owner'::text, 'Admin'::text, 'Editor'::text])))));
create policy "reposts public read" on public."reposts" as PERMISSIVE for SELECT using (true);
create policy "space messages public read" on public."space_messages" as PERMISSIVE for SELECT using ((is_staff() OR owns_profile(user_id) OR (EXISTS ( SELECT 1
   FROM spaces s
  WHERE ((s.id = space_messages.space_id) AND (s.host_id = current_profile_id())))) OR (EXISTS ( SELECT 1
   FROM space_participants sp
  WHERE ((sp.space_id = space_messages.space_id) AND (sp.user_id = current_profile_id()))))));
create policy "space messages self delete" on public."space_messages" as PERMISSIVE for DELETE to authenticated using ((owns_profile(user_id) OR is_staff()));
create policy "space messages self write" on public."space_messages" as PERMISSIVE for INSERT to authenticated with check ((owns_profile(user_id) AND is_active_profile()));
create policy "space participants public read" on public."space_participants" as PERMISSIVE for SELECT using (true);
create policy "space participants self delete" on public."space_participants" as PERMISSIVE for DELETE to authenticated using ((owns_profile(user_id) OR (EXISTS ( SELECT 1
   FROM spaces s
  WHERE ((s.id = space_participants.space_id) AND owns_profile(s.host_id))))));
create policy "space participants self update" on public."space_participants" as PERMISSIVE for UPDATE to authenticated using ((owns_profile(user_id) OR (EXISTS ( SELECT 1
   FROM spaces s
  WHERE ((s.id = space_participants.space_id) AND owns_profile(s.host_id))))));
create policy "space participants self write" on public."space_participants" as PERMISSIVE for INSERT to authenticated with check ((owns_profile(user_id) AND ((role = 'listener'::text) OR is_staff() OR (EXISTS ( SELECT 1
   FROM spaces s
  WHERE ((s.id = space_participants.space_id) AND owns_profile(s.host_id)))))));
create policy "space replay views read" on public."space_replay_views" as PERMISSIVE for SELECT using ((is_staff() OR owns_profile(user_id) OR (EXISTS ( SELECT 1
   FROM spaces s
  WHERE ((s.id = space_replay_views.space_id) AND (s.host_id = current_profile_id()))))));
create policy "space replay views self write" on public."space_replay_views" as PERMISSIVE for INSERT to authenticated with check (owns_profile(user_id));
create policy "spaces host delete" on public."spaces" as PERMISSIVE for DELETE to authenticated using ((owns_profile(host_id) OR is_staff()));
create policy "spaces host update" on public."spaces" as PERMISSIVE for UPDATE to authenticated using ((owns_profile(host_id) OR is_staff()));
create policy "spaces host write" on public."spaces" as PERMISSIVE for INSERT to authenticated with check (owns_profile(host_id));
create policy "spaces public read" on public."spaces" as PERMISSIVE for SELECT using ((live OR ((starts_at IS NOT NULL) AND (starts_at > (now() - '7 days'::interval))) OR owns_profile(host_id) OR is_staff()));
create policy "stories graph read" on public."stories" as PERMISSIVE for SELECT using ((is_staff() OR owns_profile(user_id) OR ((expires_at > now()) AND ((EXISTS ( SELECT 1
   FROM follows f
  WHERE ((f.follower_id = current_profile_id()) AND (f.target_id = stories.user_id)))) OR (EXISTS ( SELECT 1
   FROM follows f
  WHERE ((f.follower_id = stories.user_id) AND (f.target_id = current_profile_id()))))))));
create policy "stories owner delete" on public."stories" as PERMISSIVE for DELETE to authenticated using ((owns_profile(user_id) OR is_staff()));
create policy "stories owner update" on public."stories" as PERMISSIVE for UPDATE to authenticated using ((owns_profile(user_id) OR is_staff()));
create policy "stories owner write" on public."stories" as PERMISSIVE for INSERT to authenticated with check (owns_profile(user_id));
create policy "story likes owner delete" on public."story_likes" as PERMISSIVE for DELETE to authenticated using (owns_profile(user_id));
create policy "story likes owner write" on public."story_likes" as PERMISSIVE for INSERT to authenticated with check (owns_profile(user_id));
create policy "story likes public read" on public."story_likes" as PERMISSIVE for SELECT using (true);
create policy "subscriptions no client write" on public."subscriptions" as PERMISSIVE for ALL to authenticated using (false) with check (false);
create policy "subscriptions owner read" on public."subscriptions" as PERMISSIVE for SELECT to authenticated using ((owns_profile(user_id) OR is_staff()));
create policy "ticket messages read" on public."support_ticket_messages" as PERMISSIVE for SELECT to authenticated using ((is_staff() OR (EXISTS ( SELECT 1
   FROM support_tickets t
  WHERE ((t.id = support_ticket_messages.ticket_id) AND owns_profile(t.user_id))))));
create policy "ticket messages write" on public."support_ticket_messages" as PERMISSIVE for INSERT to authenticated with check ((is_staff() OR (EXISTS ( SELECT 1
   FROM support_tickets t
  WHERE ((t.id = support_ticket_messages.ticket_id) AND owns_profile(t.user_id))))));
create policy "tickets owner all" on public."support_tickets" as PERMISSIVE for ALL to authenticated using ((owns_profile(user_id) OR is_staff())) with check ((owns_profile(user_id) OR is_staff()));
create policy "system settings admin write" on public."system_settings" as PERMISSIVE for UPDATE to authenticated using (has_role(auth.uid(), 'admin'::app_role));
create policy "system settings read" on public."system_settings" as PERMISSIVE for SELECT using (true);
create policy "tips participant read" on public."tips" as PERMISSIVE for SELECT to authenticated using ((owns_profile(from_user_id) OR owns_profile(to_user_id) OR is_staff()));
create policy "tips sender write" on public."tips" as PERMISSIVE for INSERT to authenticated with check (owns_profile(from_user_id));
create policy "prefs owner all" on public."user_preferences" as PERMISSIVE for ALL to authenticated using (owns_profile(user_id)) with check (owns_profile(user_id));
create policy "roles admin write" on public."user_roles" as PERMISSIVE for ALL to authenticated using (has_role(auth.uid(), 'admin'::app_role)) with check (has_role(auth.uid(), 'admin'::app_role));
create policy "roles self read" on public."user_roles" as PERMISSIVE for SELECT to authenticated using (((user_id = auth.uid()) OR is_staff()));
create policy "deliveries owner read" on public."webhook_deliveries" as PERMISSIVE for SELECT to authenticated using ((webhook_id IN ( SELECT w.id
   FROM (webhooks w
     JOIN profiles p ON ((p.id = w.user_id)))
  WHERE (p.auth_user_id = auth.uid()))));
create policy "webhooks owner all" on public."webhooks" as PERMISSIVE for ALL to authenticated using (owns_profile(user_id)) with check (owns_profile(user_id));
create policy "workspace members manage delete" on public."workspace_members" as PERMISSIVE for DELETE to authenticated using (((workspace_role(workspace_id, current_profile_id()) = ANY (ARRAY['Owner'::text, 'Admin'::text])) OR (user_id = current_profile_id())));
create policy "workspace members manage insert" on public."workspace_members" as PERMISSIVE for INSERT to authenticated with check (((workspace_role(workspace_id, current_profile_id()) = ANY (ARRAY['Owner'::text, 'Admin'::text])) AND ((role <> 'Owner'::text) OR (workspace_role(workspace_id, current_profile_id()) = 'Owner'::text))));
create policy "workspace members manage update" on public."workspace_members" as PERMISSIVE for UPDATE to authenticated using ((workspace_role(workspace_id, current_profile_id()) = ANY (ARRAY['Owner'::text, 'Admin'::text]))) with check ((((workspace_role(workspace_id, current_profile_id()) = ANY (ARRAY['Owner'::text, 'Admin'::text])) AND (role <> 'Owner'::text)) OR (workspace_role(workspace_id, current_profile_id()) = 'Owner'::text)));
create policy "workspace members read" on public."workspace_members" as PERMISSIVE for SELECT to authenticated using ((is_workspace_member(workspace_id, current_profile_id()) OR (user_id = current_profile_id())));
create policy "workspace payout owner all" on public."workspace_payout_details" as PERMISSIVE for ALL to authenticated using ((workspace_role(workspace_id, current_profile_id()) = 'Owner'::text)) with check ((workspace_role(workspace_id, current_profile_id()) = 'Owner'::text));
create policy "workspaces member read" on public."workspaces" as PERMISSIVE for SELECT to authenticated using (((owner_id = current_profile_id()) OR (EXISTS ( SELECT 1
   FROM workspace_members m
  WHERE ((m.workspace_id = workspaces.id) AND (m.user_id = current_profile_id()))))));
create policy "workspaces owner delete" on public."workspaces" as PERMISSIVE for DELETE to authenticated using (owns_profile(owner_id));
create policy "workspaces owner update" on public."workspaces" as PERMISSIVE for UPDATE to authenticated using ((workspace_role(id, current_profile_id()) = ANY (ARRAY['Owner'::text, 'Admin'::text]))) with check ((workspace_role(id, current_profile_id()) = ANY (ARRAY['Owner'::text, 'Admin'::text])));
create policy "workspaces owner write" on public."workspaces" as PERMISSIVE for INSERT to authenticated with check ((owns_profile(owner_id) AND is_pro_profile(owner_id)));

